import { BaseTeamInfo, BaseMapInfo, SessionBasedGameSetupOptions, TeamPadInfo } from "./types"
import { SessionBasedPlayer } from "./SessionBasedPlayer"
import { BlockName, CustomTextStyling, PlayerId, PNull, Pos, RecursiveReadonly } from "@bloxd"
import { style, getDimensions, getLowHigh, displayMs } from "./helpers"
import { forceLoadChunk, setInterval, shuffleArray, getRandomItem } from "@plugins/helpers"
import { MapVoter } from "./MapVoter"

export class SessionBasedGame<TeamInfo extends BaseTeamInfo, MapInfo extends BaseMapInfo<TeamInfo>, Player extends SessionBasedPlayer<TeamInfo, MapInfo>> {
	gamePhase: "beforeGame" | "inGame" | "gameFinished" = "beforeGame"
	private startingRound = false
	private players: Record<PlayerId, Player> = {}
	map: PNull<MapInfo> = null
	private gameStartTime: number = 0
	private startGameAt: number = Infinity
	private endGameAt: number = Infinity
	private mapVoter: MapVoter<TeamInfo, MapInfo>

	messageColours = {
		error: "#ff0000",
		success: "#00ff00",
		info: "#ffffff",
	}

	private get playersForFullLobby() {
		return this.gameOptions.teams.reduce((a, b) => {
			return a + b.maxPlayers
		}, 0)
	}

	private get playerCount() {
		return Object.keys(this.players).length
	}

	constructor(readonly gameOptions: Required<SessionBasedGameSetupOptions<TeamInfo, MapInfo, Player>>) {
		this.mapVoter = new MapVoter(this.gameOptions.maps, this.players)
		this.resetGame(false)
		setInterval(() => {
			this.sendRightInfoText()
		}, 1000)
	}

	/**
	 * Gets the player object for a given player ID.
	 * @param playerId The player ID to get the player for
	 */
	getPlayer(playerId: PlayerId) {
		return this.players[playerId]
	}

	/**
	 * Gets all the players in the game, including spectators.
	 * @returns An iterator of all the players in the game.
	 */
	*getPlayers(): Generator<Player> {
		for (const playerId in this.players) {
			yield this.players[playerId]
		}
	}

	getStartingInText(): string | CustomTextStyling {
		if (this.gamePhase !== "beforeGame") {
			return []
		}
		const timeLeft = this.startGameAt - api.now()
		if (timeLeft < 0) {
			return []
		}
		return [
			...style({ translationKey: "sessionBasedGame:startingIn" }, this.messageColours.info),
			" ",
			...style(`${displayMs(timeLeft)}`, timeLeft < 10_000 ? this.messageColours.success : this.messageColours.info),
		]
	}
	/**
	 * Gives all players coloured armour based on their team name. Spectators will get black armour.
	 * If their team name is not a valid colour, they will be skipped.
	 */
	giveColouredArmourToEveryone() {
		for (const playerId in this.players) {
			const player = this.players[playerId]
			const prefix = player.team ? player.team.name : "Black"
			try {
				api.setItemSlot(playerId, 46, `${prefix} Wood Helmet`)
				api.setItemSlot(playerId, 47, `${prefix} Wood Chestplate`)
				api.setItemSlot(playerId, 48, `${prefix} Wood Gauntlets`)
				api.setItemSlot(playerId, 49, `${prefix} Wood Leggings`)
				api.setItemSlot(playerId, 50, `${prefix} Wood Boots`)
			} catch (e) {
				api.log(`Error giving coloured armour to player ${playerId}: ${e}`)
			}
		}
	}

	onPlayerJoin(playerId: PlayerId) {
		this.players[playerId] = new this.gameOptions.playerConstructor(playerId, this)
		this.mapVoter.onPlayerJoin(playerId)
		this.updateTimeTillStart()
	}

	onPlayerLeave(playerId: PlayerId) {
		if (!this.players[playerId]) {
			return
		}
		if (this.gamePhase === "beforeGame") {
			const requestedTeam = this.players[playerId].requestedTeam
			if (requestedTeam) {
				this.placeTeamPad(requestedTeam.name, false)
			}
		}
		delete this.players[playerId]
		this.checkWin()
		this.mapVoter.onPlayerLeave(playerId)
	}

	onPlayerDie(playerId: PlayerId) {
		this.checkWin()
	}

	checkWin() {
		if (this.gamePhase !== "inGame") {
			return
		}
		const teamsAlive = this.getTeamsAlive()
		if (teamsAlive.length === 1) {
			this.makeTeamWin(teamsAlive[0])
		}
	}

	onPlayerChat(playerId: PlayerId, message: string) {
		return this.players[playerId].onMessage()
	}

	onPlayerBoughtShopItem(playerId: PlayerId, categoryKey: string, itemKey: string) {
		this.mapVoter.onMapVote(playerId, categoryKey, itemKey)
	}

	tick() {
		this.checkGameTransition()
	}

	private getTeamsAlive() {
		const teamsAlive: TeamInfo[] = []
		for (const playerId in this.players) {
			const player = this.players[playerId]
			if (player.team && !teamsAlive.includes(player.team)) {
				teamsAlive.push(player.team)
			}
		}
		return teamsAlive
	}

	private updateTimeTillStart() {
		if (this.gamePhase === "beforeGame" && this.playerCount >= this.playersForFullLobby) {
			this.setStartGame(this.gameOptions.fullLobbyStartInSecs)
		}
	}

	private setStartGame(startInSecs: number) {
		const newStartAt = api.now() + startInSecs * 1000
		this.startGameAt = Math.min(this.startGameAt, newStartAt)
		api.broadcastMessage(style(`Starting in ${startInSecs}s...`, this.messageColours.info))
	}

	private checkGameTransition() {
		if (this.gamePhase === "beforeGame") {
			const timeLeft = this.startGameAt - api.now()
			if (timeLeft < 0) {
				if (this.playerCount < 2) {
					api.broadcastMessage(style("Not enough players to start game", this.messageColours.error))
					this.startGameAt = Infinity
					this.setStartGame(this.gameOptions.emptyLobbyStartInSecs)
				} else {
					this.startGame()
				}
				return
			} else if (timeLeft < 5_000) {
				const secsLeft = Math.ceil(timeLeft / 1000)
				for (const playerId in this.players) {
					api.setClientOption(playerId, "middleTextUpper", style(`Game starts in ${secsLeft} seconds`, this.messageColours.info))
				}
			} else {
				for (const playerId in this.players) {
					api.setClientOption(playerId, "middleTextUpper", [])
				}
			}
		}
		if (this.gamePhase === "gameFinished") {
			const timeLeft = this.endGameAt - api.now()
			if (timeLeft < 0) {
				this.resetGame(true)
			} else if (timeLeft < 5_000) {
				const secsLeft = Math.ceil(timeLeft / 1000)
				for (const playerId in this.players) {
					api.setClientOption(playerId, "middleTextUpper", style(`Game ends in ${secsLeft} seconds`, this.messageColours.info))
				}
			}
		}
	}

	private sendRightInfoText() {
		for (const playerId in this.players) {
			const rightInfoText = this.gameOptions.getRightInfoText(this.players[playerId])
			if (rightInfoText) {
				api.setClientOption(playerId, "RightInfoText", rightInfoText)
			}
		}
	}

	private loadMapFromRect(rect: RecursiveReadonly<[Pos, Pos]>) {
		const mapDimensions = getDimensions(rect)
		const { low: mapLow } = getLowHigh(rect)

		const { low: playAreaLow, high: playAreaHigh } = getLowHigh(this.gameOptions.playAreaRect)

		for (let x = 0; x < mapDimensions.l; x += 32) {
			for (let y = 0; y < mapDimensions.w; y += 32) {
				for (let z = 0; z < mapDimensions.h; z += 32) {
					const mapChunkPos: Pos = [mapLow[0] + x, mapLow[1] + y, mapLow[2] + z]
					const playAreaChunkPos: Pos = [playAreaLow[0] + x, playAreaLow[1] + y, playAreaLow[2] + z]

					forceLoadChunk(mapChunkPos[0], mapChunkPos[1], mapChunkPos[2], () => {
						api.copyChunk(mapChunkPos, playAreaChunkPos)
					})
				}
			}
		}

		// Replace the rest of the play area with air
		const mapEnd: Pos = [playAreaLow[0] + mapDimensions.l, playAreaLow[1] + mapDimensions.w, playAreaLow[2] + mapDimensions.h]
		fillOutsideWithAir(playAreaLow, playAreaHigh, mapEnd)
	}

	private startGame() {
		api.setMaxPlayers(1, this.playersForFullLobby + this.gameOptions.maxSpectators)

		this.assignTeams()

		this.map = null
		if (this.gameOptions.mapVotingEnabled) {
			this.map = this.mapVoter.chooseMap()
			this.mapVoter.endMapVoting()
		}

		if (!this.map) {
			this.map = getRandomItem(this.gameOptions.maps)
		}

		// finally: a throw here leaves the game in beforeGame, and a startingRound stuck true
		// would fade every player in the lobby it resets to
		this.startingRound = true
		try {
			for (const playerId in this.players) {
				api.setClientOption(playerId, "middleTextUpper", [])
				if (this.players[playerId].team) {
					this.players[playerId].startPlaying()
				} else {
					this.players[playerId].startSpectating()
				}
			}

			this.loadMapFromRect(this.map.source.rect)

			this.gameStartTime = api.now()
			this.gamePhase = "inGame"
		} finally {
			this.startingRound = false
		}
		this.gameOptions.onStart()
	}

	/**
	 * Whether spectators should render faded. gamePhase can't be read directly: it only flips to
	 * "inGame" once startGame() has started every player, and the sit-out spectators it makes
	 * along the way need fading too.
	 */
	spectatorsAreFaded(): boolean {
		return this.startingRound || this.gamePhase === "inGame"
	}

	private assignTeams() {
		const teamCounts = Object.fromEntries(
			this.gameOptions.teams.map((team) => {
				return [team.name, 0]
			}),
		) as Record<string, number>
		const requestedPlayers: PlayerId[] = []
		const unrequestedPlayers: PlayerId[] = []
		for (const playerId in this.players) {
			const player = this.players[playerId]
			if (player.requestedTeam) {
				requestedPlayers.push(playerId)
			} else {
				unrequestedPlayers.push(playerId)
			}
		}
		shuffleArray(unrequestedPlayers)
		const playerIds = [...requestedPlayers, ...unrequestedPlayers]
		for (const playerId of playerIds) {
			const player = this.players[playerId]
			if (player.requestedTeam) {
				player.team = player.requestedTeam
				teamCounts[player.requestedTeam.name]++
				continue
			}
			let smallestTeamPlayers = Infinity
			let smallestTeam: PNull<TeamInfo> = null
			for (const team of this.gameOptions.teams) {
				const numOnTeam = teamCounts[team.name]
				if (numOnTeam < smallestTeamPlayers && numOnTeam < team.maxPlayers) {
					smallestTeamPlayers = numOnTeam
					smallestTeam = team
				}
			}
			if (smallestTeam === null) {
				continue
			}
			this.players[playerId].team = smallestTeam
			teamCounts[smallestTeam.name]++
		}
	}

	/**
	 * Manually sets a team to win the game. Will begin the game reset timer to restart the game.#
	 * Automatically called when there is only one team left.
	 * @param winningTeam - The team object that won the game.
	 */
	makeTeamWin(winningTeam: PNull<TeamInfo>) {
		if (this.gamePhase !== "inGame") {
			return
		}
		this.gamePhase = "gameFinished"
		this.gameOptions.onFinish(winningTeam)
		this.endGameAt = api.now() + this.gameOptions.gameResetInSecs * 1000
	}

	private resetGame(restart: boolean) {
		this.gamePhase = "beforeGame"
		this.startGameAt = Infinity
		this.endGameAt = Infinity
		for (const playerId in this.players) {
			const player = this.players[playerId]
			player.startSpectating()
			player.requestedTeam = null
			if (restart) {
				api.killLifeform(playerId)
			}
		}
		api.setMaxPlayers(this.playersForFullLobby, this.playersForFullLobby + this.gameOptions.maxSpectators)
		this.loadMapFromRect(this.gameOptions.lobby.source.rect)
		if (this.gameOptions.lobby.teamPads) {
			this.placeTeamPads()
		}
		this.setStartGame(this.gameOptions.emptyLobbyStartInSecs)
		if (this.gameOptions.mapVotingEnabled) {
			this.mapVoter.createMapVoting()
		}
	}

	onBlockStandStart(playerId: PlayerId, x: number, y: number, z: number, blockName: BlockName) {
		if (!this.gameOptions.lobby.teamPads) {
			return
		}
		if (this.gamePhase !== "beforeGame") {
			return
		}
		const player = this.players[playerId]
		let team: PNull<TeamInfo> = null
		const { low: playAreaLow, high: playAreaHigh } = getLowHigh(this.gameOptions.playAreaRect)
		for (const teamPadName in this.gameOptions.lobby.teamPads) {
			const teamPadInfo = this.gameOptions.lobby.teamPads[teamPadName]
			const { low: rectLow, high: rectHigh } = getLowHigh(teamPadInfo.rect)
			rectLow[0] += playAreaLow[0]
			rectLow[1] += playAreaLow[1]
			rectLow[2] += playAreaLow[2]
			rectHigh[0] += playAreaLow[0]
			rectHigh[1] += playAreaLow[1]
			rectHigh[2] += playAreaLow[2]
			if (api.isInsideRect([x, y, z], rectLow, rectHigh)) {
				team = this.gameOptions.teams.find((team) => {
					return team.name === teamPadName
				})
				break
			}
		}
		if (!team) {
			return
		}

		const oldTeam = player.requestedTeam
		if (oldTeam === team) {
			return
		}

		let requestCount = 0
		for (const playerId in this.players) {
			const player = this.players[playerId]
			if (player.requestedTeam === team) {
				requestCount++
			}
		}

		if (player.qTextId) {
			api.removeFromQueue(player.qTextId)
		}
		if (requestCount >= team.maxPlayers) {
			if (player.requestedTeam !== team) {
				player.qTextId = api.queueMiddleTextLower(playerId, style(`${team.name} team is full`, this.messageColours.error), 1000)
			}
			// Unneeded, but nice sanity check
			this.placeTeamPad(team.name, true)
			return
		}

		player.requestedTeam = team

		player.qTextId = api.queueMiddleTextLower(playerId, style(`${team.name} team selected`, this.messageColours.success), 1000)
		if (oldTeam !== team) {
			if (oldTeam) {
				this.placeTeamPad(oldTeam.name, false)
			}
			const isFull = requestCount + 1 >= team.maxPlayers
			this.placeTeamPad(team.name, isFull)
		}
	}

	private placeTeamPad(teamName: string, full: boolean) {
		const { low: playAreaLow } = getLowHigh(this.gameOptions.playAreaRect)
		const { rect, emptyBlock, fullBlock } = this.gameOptions.lobby.teamPads[teamName]
		// Only force load the first chunk - assumes the rest of the chunk is already loaded
		const { low: rectLow, high: rectHigh } = getLowHigh(rect)
		for (let x = rectLow[0] + playAreaLow[0]; x <= rectHigh[0] + playAreaLow[0]; x += 32) {
			for (let y = rectLow[1] + playAreaLow[1]; y <= rectHigh[1] + playAreaLow[1]; y += 32) {
				for (let z = rectLow[2] + playAreaLow[2]; z <= rectHigh[2] + playAreaLow[2]; z += 32) {
					forceLoadChunk(x, y, z, () => {
						const endX = Math.min(x + 31, rectHigh[0] + playAreaLow[0])
						const endY = Math.min(y + 31, rectHigh[1] + playAreaLow[1])
						const endZ = Math.min(z + 31, rectHigh[2] + playAreaLow[2])
						fillBox([x, y, z], [endX, endY, endZ], full ? fullBlock : emptyBlock)
					})
				}
			}
		}
	}

	private placeTeamPads() {
		for (const teamName in this.gameOptions.lobby.teamPads) {
			this.placeTeamPad(teamName, false)
		}
	}
}

function fillOutsideWithAir(low: Pos, high: Pos, copiedHigh: Pos) {
	for (let axis = 0; axis < 3; axis++) {
		const slabLow: Pos = [low[0], low[1], low[2]]
		const slabHigh: Pos = [high[0], high[1], high[2]]
		slabLow[axis] = copiedHigh[axis] + 1

		// Avoid overlapping slabs (no point setting blocks already set)
		for (let earlier = 0; earlier < axis; earlier++) {
			slabHigh[earlier] = Math.min(copiedHigh[earlier], high[earlier])
		}

		if (slabLow[0] <= slabHigh[0] && slabLow[1] <= slabHigh[1] && slabLow[2] <= slabHigh[2]) {
			fillBox(slabLow, slabHigh, "Air")
		}
	}
}

function fillBox(pos1: Pos, pos2: Pos, block: BlockName) {
	// api.setBlockRect caps at 360 blocks; slice along Z, then Y, then X so each call stays under the cap.
	const maxRectVol = 360
	const {
		low: [x1, y1, z1],
		high: [x2, y2, z2],
	} = getLowHigh([pos1, pos2])
	const zSizeFull = z2 - z1 + 1
	const zStep = Math.min(zSizeFull, maxRectVol)
	for (let z = z1; z <= z2; z += zStep) {
		const zEnd = Math.min(z2, z + zStep - 1)
		const zSize = zEnd - z + 1
		const yStep = Math.max(1, Math.floor(maxRectVol / zSize))
		for (let y = y1; y <= y2; y += yStep) {
			const yEnd = Math.min(y2, y + yStep - 1)
			const yz = (yEnd - y + 1) * zSize
			const xStep = Math.max(1, Math.floor(maxRectVol / yz))
			for (let x = x1; x <= x2; x += xStep) {
				const xEnd = Math.min(x2, x + xStep - 1)
				api.setBlockRect([x, y, z], [xEnd, yEnd, zEnd], block)
			}
		}
	}
}
